import sys

class InputReader:
    def next(self):
        raise NotImplementedError

    def nextInt(self):
        raise NotImplementedError

class ScannerInputReader(InputReader):
    def __init__(self, scanner):
        self.scanner = scanner
        self.tokens = []
        self.index = 0

    def next(self):
        while self.index >= len(self.tokens):
            line = self.scanner.readline()
            if not line:
                return ''
            self.tokens = line.strip().split()
            self.index = 0
        token = self.tokens[self.index]
        self.index += 1
        return token

    def nextInt(self):
        return int(self.next())

class NumberTheory:
    class Mod998:
        def __init__(self):
            self.mod = 998244353
            self.fact = [1]
            self.inv_fact = [1]

        def modinv(self, a):
            return pow(a, self.mod - 2, self.mod)

        def prepare_factorials(self, max_n):
            for i in range(len(self.fact), max_n + 1):
                self.fact.append(self.fact[-1] * i % self.mod)
            self.inv_fact = [1] * (max_n + 1)
            self.inv_fact[max_n] = self.modinv(self.fact[max_n])
            for i in range(max_n - 1, -1, -1):
                self.inv_fact[i] = self.inv_fact[i + 1] * (i + 1) % self.mod

        def ncr(self, n, r):
            if r < 0 or r > n:
                return 0
            return self.fact[n] * self.inv_fact[r] % self.mod * self.inv_fact[n - r] % self.mod

        def add(self, a, b):
            return (a + b) % self.mod

        def subtract(self, a, b):
            return (a - b) % self.mod

        def mult(self, a, b, c=1):
            return (a * b * c) % self.mod

        def smallInv(self, a):
            return self.modinv(a)

        def fInv(self, n):
            self.prepare_factorials(n)

class HZSShufflesCards:
    def __init__(self):
        self.mod = NumberTheory.Mod998()

    def solve(self, in_reader, out):
        n = in_reader.nextInt()
        m = in_reader.nextInt()

        self.mod.fInv(n + m)

        phaseSize = 1
        p = 1
        i = 0
        while p != 0:
            p = self.mod.mult(p, n - i, self.mod.smallInv(n + m - i))
            phaseSize = self.mod.add(phaseSize, p)
            i += 1

        answer = 0
        for k in range(1, n + 1):
            numPhases = self.mod.mult(m + k, self.mod.smallInv(k))
            term = self.mod.mult(self.mod.ncr(n, k), numPhases, phaseSize)
            if k % 2 == 1:
                answer = self.mod.add(answer, term)
            else:
                answer = self.mod.subtract(answer, term)

        out.write(str(answer) + '\n')

def main():
    scanner = sys.stdin
    in_reader = ScannerInputReader(scanner)
    out = sys.stdout
    solver = HZSShufflesCards()
    solver.solve(in_reader, out)

if __name__ == "__main__":
    main()

